about even with builtin:starter. Starter rules in priority order become scores."""

@gene('s1', 'value of doing this option now: finish wounded champions, step toward goals scaled by progress and carried gems')
def score(o: Option) -> Num:
    if o.kind == PICK:
        return 1
    if o.kind == BUY:
        return 100 if o.item == 6 else 0
    if o.kind == RECALL:
        return 90 if me().health_frac < 0.3174 else 0
    if o.kind == ATTACK:
